<script lang="ts">
  import { onDestroy, untrack } from 'svelte';
  import type { OptionsResearchToolProps, LifecycleRequest, LifecycleResponse } from '$lib/features/options/optionsResearchTypes';
  import { evaluateLifecycle } from '$lib/features/options/optionsResearchApi';
  import { emptyResearchState, inputKey, lifecycleRequest, MAX_PATH_TEXT, observationIndex, pathChart, pathControls, ResearchJob, researchValue as value, validLifecycle, type PathControls, type ResearchState } from '$lib/features/options/optionsLifecycle';

  // The hedge lab reuses only the path inputs; this mode never submits lifecycle work.
  let { draft, onEdit: _onEdit, documentKey, readOnly = false, inputsOnly = false, controls = $bindable<PathControls | undefined>() }: OptionsResearchToolProps & { inputsOnly?: boolean; controls?: PathControls } = $props();
  const uid = $props.id();
  let ownControls = $state<PathControls>(untrack(() => pathControls(draft)));
  const settings = $derived(controls ?? ownControls);
  let runState = $state.raw<ResearchState<LifecycleResponse>>(emptyResearchState(untrack(() => documentKey)));
  const job = new ResearchJob<LifecycleRequest, LifecycleResponse>(untrack(() => documentKey), () => documentKey, next => { runState = next; }, () => key);
  const prepared = $derived(lifecycleRequest(draft, settings));
  const key = $derived(inputKey(draft, settings));
  const visible = $derived(runState.documentKey === documentKey ? runState : null);
  const result = $derived(visible?.result ?? null);
  const stale = $derived(!!result && key !== visible?.submittedKey);
  let index = $state(0);
  let playing = $state(false);
  const active = $derived(result?.ledger[Math.min(index, result.ledger.length - 1)]);
  const chart = $derived(pathChart(result?.ledger.map(row => ({ day: row.day, values: [row.total_pnl, row.remaining_value, row.cumulative_settlement_cash] })) ?? []));
  $effect.pre(() => {
    const document = documentKey;
    untrack(() => { job.reset(document); ownControls = pathControls(draft); if (controls !== undefined) controls = pathControls(draft); index = 0; playing = false; });
  });
  $effect(() => {
    if (!playing || !result) return;
    const timer = setInterval(() => { if (index >= result.ledger.length - 1) playing = false; else index++; }, 500);
    return () => clearInterval(timer);
  });
  onDestroy(() => job.reset('unmounted'));
  $effect(() => { key; readOnly; untrack(() => { if (runState.pending) job.cancel(); }); });
  async function submit() {
    if (readOnly || inputsOnly || !prepared.request || visible?.pending) return;
    playing = false; index = 0;
    await job.submit(structuredClone($state.snapshot(prepared.request)), key, evaluateLifecycle, validLifecycle);
  }
  function move(key: string) {
    const next = observationIndex(index, result?.ledger.length ?? 0, key);
    if (next !== null) { playing = false; index = next; }
  }
  function editCsv(text: string) { if (!readOnly) settings.csv = text.slice(0, MAX_PATH_TEXT); }
</script>

{#snippet fieldError(key: string)}
  {#if prepared.errors[key]}<small id={`${uid}-${key}-error`} class="error">{prepared.errors[key]}</small>{/if}
{/snippet}

<section class="lifecycle" aria-label={inputsOnly ? 'Hypothetical path inputs' : 'Options multi-expiry lifecycle'}>
  {#if !inputsOnly}<header><h3>Multi-expiry lifecycle</h3><span>European · cash-settled · USD</span></header>{/if}
  <p class="note">Hypothetical path research, not historical options replay. Backend prices each observation and settles each expiry once. Later legs remain theoretical marks, not realized payoff. Between observations, expiry spot is linearly interpolated and disclosed.</p>
  {#if readOnly}<p class="notice">Read-only source mode. Switch explicitly to the visual draft editor to change or submit research inputs.</p>{/if}
  <fieldset disabled={readOnly}>
    <legend>Path assumptions · no automatic requests</legend>
    <label>Path source<select bind:value={settings.source}><option value="synthetic">Seeded synthetic · generated by backend</option><option value="supplied">User-supplied day / spot observations</option></select></label>
    {#if settings.source === 'supplied'}
      <label>Path CSV · day,spot (USD), up to 366 observations<textarea rows="6" maxlength={MAX_PATH_TEXT} value={settings.csv} aria-invalid={!!prepared.errors.csv} aria-describedby={`${uid}-csv-note ${uid}-csv-error`} oninput={e => editCsv(e.currentTarget.value)} spellcheck="false"></textarea></label>
      <p id={`${uid}-csv-note`} class="note">Optional day,spot header. Days 0–3650, strictly increasing. Spots 0–1,000,000 USD. Start at day 0 / draft spot {value(draft.spot)} USD and cover every active expiry. Edit cells in CSV; all rows remain explicit supplied assumptions, not provider history.</p>
      {@render fieldError('csv')}
    {:else}
      <div class="fields">
        {#each ([['seed', 'Seed · uint32', 0, 4294967295, '1'], ['horizon', 'Horizon · calendar days (>0–3650)', 0, 3650, 'any'], ['steps', 'Steps · 1–365', 1, 365, '1'], ['drift', 'Annual drift · fraction (−1–1)', -1, 1, 'any'], ['volatility', 'Annual path volatility · fraction (0–5)', 0, 5, 'any']] as const) as [field, label, min, max, step]}
          <label>{label}<input type="number" {min} {max} {step} value={settings[field]} aria-invalid={!!prepared.errors[field]} aria-describedby={`${uid}-${field}-error`} oninput={e => { settings[field] = e.currentTarget.value; }} />{@render fieldError(field)}</label>
        {/each}
      </div>
      <p class="note">gbm_seeded_v1 starts at submitted spot. Generation happens only on explicit submission. Seed reproduces this generator version, not market history; drift/path volatility are user assumptions, not forecasts or per-leg IV overrides.</p>
    {/if}
  </fieldset>
  {#if !inputsOnly}
    {#if Object.keys(prepared.errors).length}
      <details><summary>Input errors · {Object.keys(prepared.errors).length}</summary><ul>{#each Object.entries(prepared.errors) as [field, message]}<li><strong>{field}</strong>: {message}</li>{/each}</ul></details>
    {/if}
    <div class="actions">
      <button type="button" class="ot-workbench-primary" disabled={readOnly || !prepared.request || !!visible?.pending} onclick={submit}>{visible?.pending ? (result ? 'Refreshing lifecycle…' : 'Evaluating lifecycle…') : 'Evaluate lifecycle'}</button>
      <button type="button" class="ot-workbench-ghost" disabled={!visible?.pending} onclick={() => { playing = false; job.cancel(); }}>Cancel request</button>
    </div>
    <div class="feedback" aria-live="polite" aria-atomic="true">
      {#if visible?.pending}<p>{result ? 'Refreshing; previous submitted evidence is retained below.' : 'Evaluating the submitted path; no result yet.'}</p>{/if}
      {#if visible?.error}<p role="alert" class="error">{visible.error}</p>{/if}
      {#if visible?.notice}<p>{visible.notice}</p>{/if}
      {#if stale}<p class="notice">STALE INPUTS · Draft or path settings changed. Explicitly evaluate again; old results are not repriced.</p>{/if}
    </div>
    {#if !result && !visible?.pending}<p class="note">No lifecycle evidence. Supply a path and evaluate explicitly. Results are session-local and are not saved with the draft.</p>{/if}
    {#if result}
      <h4>{visible?.pending ? 'REFRESHING' : stale ? 'STALE INPUTS' : 'SUBMITTED EVIDENCE'} · {result.request.analysis.strategy.name}</h4>
      <p class="note">Source: {result.request.path.source === 'synthetic' ? `seeded synthetic · seed ${result.request.path.seed ?? 1} · ${result.request.path.generator ?? 'gbm_seeded_v1'}` : 'user-supplied observations · not verified history'}. {result.provenance.model} v{result.provenance.version} · {result.provenance.day_basis}. No financing, dividend cash flows, assignment, reinvestment or duplicated entry fees.</p>
      <p class="readout">Fixed net entry cost: {value(result.net_entry_cost)} USD. Final path P&amp;L: {value(result.final_pnl)} USD. P&amp;L = cumulative settlement cash + remaining marked value − fixed entry cost.</p>
      {#each result.warnings as warning}<p class="notice">{warning}</p>{/each}
      <!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard access to bounded chart scrolling.) -->
      <div class="chart-scroll" tabindex="0" role="region" aria-label="Lifecycle P and L chart; scroll horizontally. Use observation controls below to navigate.">
        <svg viewBox="0 0 660 220" role="img" aria-labelledby={`${uid}-chart-title ${uid}-chart-desc`}>
          <title id={`${uid}-chart-title`}>Submitted lifecycle · USD over elapsed calendar days</title>
          <desc id={`${uid}-chart-desc`}>Solid: P and L. Dashed: remaining marked value. Dotted: cumulative cash settlements. Full numeric tables follow. Only returned observations are shown.</desc>
          <line x1="50" x2="630" y1={chart.y(0)} y2={chart.y(0)} class="axis" />
          {#each chart.paths as path, i}<path d={path} class={`series series-${i}`} />{/each}
          {#if active}<line x1={chart.x(active.day)} x2={chart.x(active.day)} y1="25" y2="185" class="cursor" />{/if}
          <text x="50" y="15">{value(chart.max)} USD</text><text x="50" y="200">{value(chart.min)} USD</text>
          <text x="50" y="216">Day {value(result.ledger[0].day)}</text><text x="630" y="216" text-anchor="end">Day {value(result.ledger[result.ledger.length - 1]?.day)}</text>
        </svg>
      </div>
      <p class="note">Solid: total P&amp;L · dashed: remaining marked value · dotted: cumulative settlements. Lines connect known returned observations; no frontend stochastic generation or pricing.</p>
      <div class="actions">
        <button type="button" class="ot-workbench-ghost" onclick={() => { if (index >= result.ledger.length - 1) index = 0; playing = !playing; }}>{playing ? 'Pause observations' : 'Play observations'}</button>
        <button type="button" class="ot-workbench-ghost" disabled={index <= 0} onclick={() => move('ArrowLeft')}>Previous</button>
        <button type="button" class="ot-workbench-ghost" disabled={index >= result.ledger.length - 1} onclick={() => move('ArrowRight')}>Next</button>
      </div>
      <label>Chart observation · arrows / Home / End<input type="range" min="0" max={result.ledger.length - 1} step="1" value={index} aria-valuetext={active ? `Day ${active.day}, spot ${active.spot} USD, total P and L ${active.total_pnl} USD` : 'No observation'} oninput={e => { playing = false; index = e.currentTarget.valueAsNumber; }} /></label>
      {#if active}
        <p class="readout" aria-live="polite">Observation {index + 1}/{result.ledger.length} · day {value(active.day)} · spot {value(active.spot)} USD · P&amp;L {value(active.total_pnl)} USD · remaining mark {value(active.remaining_value)} USD · cumulative settlements {value(active.cumulative_settlement_cash)} USD.</p>
        <!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard access to bounded two-dimensional data scrolling.) -->
      <div class="table-scroll" tabindex="0" role="region" aria-label="Selected lifecycle leg marks">
          <table><caption>Selected day {value(active.day)} · remaining theoretical/share marks are not realized payoff</caption><thead><tr><th>Leg</th><th>State</th><th>Days remaining</th><th>Signed value · USD</th></tr></thead><tbody>{#each active.legs as leg}<tr><th>{leg.leg_index + 1}</th><td>{leg.state}</td><td>{value(leg.remaining_days)}</td><td>{value(leg.value)}</td></tr>{/each}</tbody></table>
        </div>
      {/if}
      <details open><summary>Per-expiry cash settlement ledger · chronological</summary>
        {#if result.settlements.length === 0}<p class="note">No option settlements (for example, shares-only strategy).</p>{:else}
          <!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard access to bounded two-dimensional data scrolling.) -->
      <div class="table-scroll" tabindex="0" role="region" aria-label="Per-expiry cash settlement ledger"><table><caption>Signed cash · USD; intrinsic · USD/unit. Interpolated expiry spots are assumptions, not observations.</caption><thead><tr><th>Leg</th><th>Day</th><th>Spot · USD</th><th>Source</th><th>Bracketing days</th><th>Intrinsic/unit</th><th>Signed cash · USD</th></tr></thead><tbody>{#each result.settlements as row}<tr><th>{row.leg_index + 1}</th><td>{value(row.day)}</td><td>{value(row.spot)}</td><td>{row.observation}</td><td>{value(row.left_day)} / {value(row.right_day)}</td><td>{value(row.intrinsic_per_unit)}</td><td>{value(row.signed_cash_flow)}</td></tr>{/each}</tbody></table></div>
        {/if}
      </details>
      <details><summary>Full lifecycle time series · chronological</summary><!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard access to bounded two-dimensional data scrolling.) -->
      <div class="table-scroll" tabindex="0" role="region" aria-label="Lifecycle time series"><table><caption>Every backend observation · elapsed calendar days and signed USD totals. Select a row to scrub.</caption><thead><tr><th>Day</th><th>Spot · USD</th><th>Step settlements</th><th>Cumulative cash</th><th>Remaining mark</th><th>Total P&amp;L</th></tr></thead><tbody>{#each result.ledger as row, i}<tr aria-current={i === index ? 'true' : undefined}><th><button type="button" class="ot-workbench-ghost" onclick={() => { playing = false; index = i; }}>Day {value(row.day)}</button></th><td>{value(row.spot)}</td><td>{value(row.settlement_cash_flow)}</td><td>{value(row.cumulative_settlement_cash)}</td><td>{value(row.remaining_value)}</td><td>{value(row.total_pnl)}</td></tr>{/each}</tbody></table></div></details>
      <details><summary>Returned submitted request · assumptions and provenance</summary><!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard access to bounded submitted-request scrolling.) -->
      <pre tabindex="0" aria-label="Submitted lifecycle request">{JSON.stringify(result.request, null, 2)}</pre></details>
    {/if}
  {/if}
</section>

<style>
  .lifecycle { min-width: 0; display: grid; gap: 8px; color: oklch(var(--foreground)); font: 12px var(--font-family-lato); }
  header, .actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; } header { justify-content: space-between; } h3, h4, p { margin: 0; } h3 { font-size: 14px; } h4 { font-size: 12px; }
  .note, small { color: oklch(var(--muted-foreground)); line-height: 1.6; overflow-wrap: anywhere; } .error { color: oklch(var(--foreground)); border-left: 3px solid oklch(var(--destructive)); padding-left: 6px; } .notice, .readout { border: 1px dashed oklch(var(--border)); padding: 8px; border-radius: 4px; overflow-wrap: anywhere; line-height: 1.6; }
  fieldset { min-width: 0; padding: 8px; border: 1px solid oklch(var(--border)); border-radius: 4px; } legend, summary { font-weight: 700; } summary { cursor: pointer; padding: 4px 0; }
  .fields { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr)); gap: 8px; } label { min-width: 0; display: flex; flex-direction: column; gap: 4px; margin: 4px 0; }
  input, select, textarea { width: 100%; min-width: 0; min-height: 28px; color: oklch(var(--foreground)); background: oklch(var(--card)); border: 1px solid oklch(var(--input)); border-radius: 4px; padding: 4px 6px; font: inherit; } textarea { resize: vertical; font-family: var(--font-mono); } input[type='range'] { padding: 0; accent-color: oklch(var(--ring)); }
  button { white-space: normal; height: auto; min-height: 28px; } .readout, pre, table { font-family: var(--font-mono); font-variant-numeric: tabular-nums; } pre { max-height: 240px; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere; }
  .table-scroll, .chart-scroll { max-width: 100%; overflow: auto; border: 1px solid oklch(var(--border)); } .table-scroll { max-height: min(320px, 55vh); } svg { display: block; min-width: 520px; width: 100%; max-height: 260px; } svg text { fill: currentColor; font: 10px var(--font-mono); }
  .axis { stroke: currentColor; opacity: .35; } .series { stroke: currentColor; fill: none; stroke-width: 2; } .series-1 { stroke-dasharray: 7 4; } .series-2 { stroke-dasharray: 2 4; } .cursor { stroke: currentColor; stroke-dasharray: 3 3; }
  table { border-collapse: collapse; width: 100%; font-size: 11px; } th, td { text-align: right; white-space: nowrap; padding: 6px; border-bottom: 1px solid oklch(var(--border)); } caption { text-align: left; white-space: normal; padding: 8px; font-family: var(--font-family-lato); } thead th { position: sticky; top: 0; background: oklch(var(--card)); } [aria-current='true'] { outline: 1px dashed currentColor; outline-offset: -1px; }
  :is(button, input, select, textarea, summary, [tabindex]):focus-visible { outline: 2px solid oklch(var(--ring)); outline-offset: 2px; } [aria-invalid='true'] { border-color: oklch(var(--destructive)); }
  @media (forced-colors: active) { :is(button, input, select, textarea, summary, [tabindex]):focus-visible { outline-color: Highlight; } input, select, textarea, .notice, .readout, .table-scroll, .chart-scroll { border-color: CanvasText; } }
  @media (pointer: coarse) { button, input, select { min-height: var(--control-touch-height); } }
  @media (prefers-reduced-motion: reduce) { * { scroll-behavior: auto; } }
</style>
